fn largest_divisor(n: i8) -> i8 {
    // Precondition from problem statement: n > 1
    let nn: i16 = n as i16;

    // Find the smallest divisor p >= 2. Then answer is n / p.
    let mut i: i16 = 2;
    while i * i <= nn {
        if nn % i == 0 {
            return (nn / i) as i8;
        }
        i += 1;
    }

    // n is prime
    1
}

